import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_FRESH_MS,
  WORKER_NAME,
  toJob,
  validateNewJob,
  type FieldError,
  type JobRow,
  type NewJob,
} from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_BODY_BYTES = 64 * 1024;

const stmts = {
  list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  insert: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ),
  heartbeat: db.prepare('SELECT at_ms FROM heartbeats WHERE name = ?'),
};

const asRow = (r: unknown) => r as JobRow | undefined;

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], extraHeaders?: Record<string, string>): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } }, extraHeaders);
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

/** Reads the whole body. Resolves to null when it exceeds MAX_BODY_BYTES (the rest is drained). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

type Submission = { status: 200 | 201; job: JobRow } | { status: 409 };

/** Creates a job, or replays/conflicts with an earlier submission that used the same idempotency key. */
function submit(value: NewJob, key: string | null): Submission {
  db.exec('BEGIN IMMEDIATE');
  let committed = false;
  try {
    if (key !== null) {
      const existing = asRow(stmts.byKey.get(key));
      if (existing) {
        db.exec('COMMIT');
        committed = true;
        const same = existing.input === value.input && existing.steps === value.steps && existing.fail_attempts === value.failAttempts;
        return same ? { status: 200, job: existing } : { status: 409 };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    stmts.insert.run(id, value.input, value.steps, value.failAttempts, key, now, now);
    const job = asRow(stmts.byId.get(id)) as JobRow;
    db.exec('COMMIT');
    committed = true;
    return { status: 201, job };
  } finally {
    if (!committed) db.exec('ROLLBACK');
  }
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  const fields: FieldError[] = [];

  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') fields.push({ field: 'Content-Type', message: 'Content-Type must be application/json' });

  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    if (typeof rawKey === 'string' && KEY_RE.test(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsed: unknown;
  if (text === null) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    try {
      parsed = JSON.parse(text);
    } catch {
      fields.push({ field: 'body', message: 'body is not valid JSON' });
    }
  }
  if (fields.length === 0 && (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
  }
  if (fields.length > 0) return invalid(res, fields);

  const validation = validateNewJob(parsed as Record<string, unknown>);
  if (!validation.ok) return invalid(res, validation.fields);

  const result = submit(validation.value, key);
  if (result.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.status, toJob(result.job));
}

function health(res: ServerResponse): void {
  const row = stmts.heartbeat.get(WORKER_NAME) as { at_ms: number } | undefined;
  const up = row !== undefined && Date.now() - Number(row.at_ms) <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function notAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow: allowed.join(', ') });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    return health(res);
  }
  if (pathname === '/') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (stmts.list.all() as unknown as JobRow[]).map(toJob) });
    if (method === 'POST') return createJob(req, res);
    return notAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    const row = asRow(stmts.byId.get(match[1]!));
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Force exit if open connections keep the server from closing.
  setTimeout(() => process.exit(0), 3000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

