import { setInterval, clearInterval } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_INTERVAL_MS,
  IDLE_POLL_MS,
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  STEP_MS,
  TRANSIENT_ERROR,
  WORKER_NAME,
  type JobRow,
} from './jobs.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const nowIso = () => new Date().toISOString();

const stmts = {
  beat: db.prepare('INSERT INTO heartbeats (name, at_ms) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms'),
  unbeat: db.prepare('DELETE FROM heartbeats WHERE name = ?'),
  recover: db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'"),
  // Claims the oldest queued job whose retry delay has passed, in one atomic statement.
  claim: db.prepare(
    `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, error = NULL, updated_at = ?
     WHERE id = (SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1)
     RETURNING *`,
  ),
  progress: db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?'),
  requeue: db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE id = ?"),
  complete: db.prepare("UPDATE jobs SET status = 'completed', progress_completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ?"),
  fail: db.prepare("UPDATE jobs SET status = 'failed', progress_completed = 0, error = ?, updated_at = ? WHERE id = ?"),
};

function beat(): void {
  stmts.beat.run(WORKER_NAME, Date.now());
}

/** Processes one claimed attempt of a job. Returns when the attempt ends, by completion, failure, or requeue. */
async function runAttempt(job: JobRow): Promise<void> {
  // Attempts up to failAttempts fail at their first step, before any progress.
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= MAX_ATTEMPTS) stmts.fail.run(TRANSIENT_ERROR, nowIso(), job.id);
    else stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      // Shutting down mid-job: leave it queued so the next worker start processes it again.
      stmts.requeue.run(0, nowIso(), job.id);
      return;
    }
    await sleep(STEP_MS);
    stmts.progress.run(step, nowIso(), job.id);
  }
  stmts.complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

async function main(): Promise<void> {
  // A job left "running" by a worker that died is processed again from the start.
  stmts.recover.run(nowIso());
  beat();
  const timer = setInterval(beat, HEARTBEAT_INTERVAL_MS);
  console.log('worker started');

  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = stmts.claim.get(nowIso(), Date.now()) as unknown as JobRow | undefined;
      if (!job) {
        await sleep(IDLE_POLL_MS);
        continue;
      }
      await runAttempt(job);
    } catch (e) {
      console.error('worker error:', e);
      await sleep(1000);
    }
  }

  clearInterval(timer);
  stmts.unbeat.run(WORKER_NAME);
  db.close();
  console.log('worker stopped');
}

main().then(
