/** Shared job definitions: row shape, API mapping, and request validation. */

export const MAX_ATTEMPTS = 3;
export const STEP_MS = 100;
export const RETRY_DELAY_MS = 500;
export const IDLE_POLL_MS = 200;
export const HEARTBEAT_INTERVAL_MS = 1000;
export const HEARTBEAT_FRESH_MS = 3000;
export const WORKER_NAME = 'worker';
export const TRANSIENT_ERROR = 'transient failure';

export interface JobRow {
  seq: number;
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

export function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? TRANSIENT_ERROR) : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type Validation = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

function intField(body: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const v = body[name];
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: `${name} must be an integer` });
    return fallback;
  }
  if (v < min || v > max) {
    fields.push({ field: name, message: `${name} must be between ${min} and ${max}` });
    return fallback;
  }
  return v;
}

/** Validates a parsed request body (already known to be a plain object). Defaults are applied here. */
export function validateNewJob(body: Record<string, unknown>): Validation {
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }
  let input = '';
  if (!Object.hasOwn(body, 'input')) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof body.input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (body.input.length < 1 || body.input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (body.input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = body.input;
  }
  const steps = intField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = intField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

