15	    .job .id { font-family: monospace; font-size: 0.75rem; color: #888; }
16	  </style>
17	</head>
18	<body>
19	  <h1>Job tracker</h1>
20	
21	  <form data-testid="job-form" id="job-form">
22	    <label for="job-input">Input</label>
23	    <input data-testid="job-input" id="job-input" name="input" type="text" autocomplete="off">
24	
25	    <label for="job-steps">Steps</label>
26	    <input data-testid="job-steps" id="job-steps" name="steps" type="text" inputmode="numeric" value="5">
27	
28	    <label for="job-fail-attempts">Fail attempts</label>
29	    <input data-testid="job-fail-attempts" id="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
30	
31	    <button data-testid="job-submit" type="submit">Submit job</button>
32	  </form>
33	
34	  <div data-testid="form-error" role="alert" id="form-error"></div>
35	
36	  <h2>Jobs</h2>
37	  <ul data-testid="job-list" id="job-list"></ul>
38	
39	  <script>
40	    const form = document.getElementById('job-form');
41	    const inputEl = document.getElementById('job-input');
42	    const stepsEl = document.getElementById('job-steps');
43	    const failEl = document.getElementById('job-fail-attempts');
44	    const submitBtn = document.querySelector('[data-testid="job-submit"]');
45	    const formError = document.getElementById('form-error');
46	    const list = document.getElementById('job-list');
47	
48	    // Empty fields are omitted so the API applies its defaults. Numeric text is sent as a number;
49	    // anything else is sent as the raw string so the API rejects it and names the field.
50	    function numericValue(text) {
51	      const t = text.trim();
52	      if (t === '') return undefined;
53	      return /^[+-]?\d+(\.\d+)?$/.test(t) ? Number(t) : t;
54	    }
55	
56	    function renderJob(job, li) {
57	      li.dataset.jobId = job.id;
58	      li.querySelector('[data-testid="job-status"]').textContent = job.status;
59	      li.querySelector('[data-testid="job-progress"]').textContent = `${job.progress.completed}/${job.progress.total}`;
60	      let result = '';
61	      if (job.status === 'completed' && job.result) result = job.result.output;
62	      else if (job.status === 'failed') result = job.error ?? '';
63	      li.querySelector('[data-testid="job-result"]').textContent = result;
64	      li.querySelector('.input').textContent = job.input;
65	    }
66	
67	    function createItem() {
68	      const li = document.createElement('li');
69	      li.setAttribute('data-testid', 'job-item');
70	      li.className = 'job';
71	      li.innerHTML = '<span data-testid="job-status"></span>'
72	        + '<span data-testid="job-progress"></span>'
73	        + '<span data-testid="job-result"></span>'
74	        + '<span class="input"></span>';
75	      return li;
76	    }
77	
78	    let items = new Map();
79	    function renderList(jobs) {
80	      const next = new Map();
81	      for (const job of jobs) {
82	        const li = items.get(job.id) ?? createItem();
83	        renderJob(job, li);
84	        next.set(job.id, li);
85	        list.appendChild(li); // appending in API order keeps newest first
86	      }
87	      for (const [id, li] of items) if (!next.has(id)) li.remove();
88	      items = next;
89	    }
90	
91	    let refreshing = false;
92	    async function refresh() {
93	      if (refreshing) return;
94	      refreshing = true;
95	      try {
96	        const res = await fetch('/api/jobs', { cache: 'no-store' });
97	        if (res.ok) renderList((await res.json()).jobs);
98	      } catch {
99	        // Server unreachable; try again on the next tick.
100	      } finally {
101	        refreshing = false;
102	      }
103	    }
104	
105	    form.addEventListener('submit', async (event) => {
106	      event.preventDefault();
107	      formError.textContent = '';
108	      submitBtn.disabled = true;
109	      const body = { input: inputEl.value };
110	      const steps = numericValue(stepsEl.value);
111	      const failAttempts = numericValue(failEl.value);
112	      if (steps !== undefined) body.steps = steps;
113	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
114	      try {
115	        const res = await fetch('/api/jobs', {
116	          method: 'POST',
117	          headers: { 'content-type': 'application/json' },
118	          body: JSON.stringify(body),
119	        });
120	        const data = await res.json().catch(() => null);
121	        if (res.ok) {
122	          inputEl.value = '';
123	          await refresh();
124	        } else {
125	          const err = data && data.error ? data.error : null;
126	          const message = err && err.message ? err.message : `Request failed (${res.status}).`;
127	          const names = err && Array.isArray(err.fields) ? err.fields.map((f) => f.field).join(', ') : '';
128	          formError.textContent = names ? `${message} Invalid fields: ${names}.` : message;
129	        }
130	      } catch {
131	        formError.textContent = 'Could not reach the server.';
132	      } finally {
133	        submitBtn.disabled = false;
134	      }
135	    });
136	
137	    refresh();
138	    setInterval(refresh, 1000);
139	  </script>
140	</body>
141	</html>
